import json
import re

# Load the schema
with open('config/output_schema.json', 'r') as f:
    schema = json.load(f)

# Load the profile
with open('output/openai_social_profile.json', 'r') as f:
    profile = json.load(f)

# Validate required fields
required = schema['required']
for field in required:
    if field not in profile:
        print(f'ERROR: Missing required field: {field}')
    else:
        print(f'✓ Required field present: {field}')

# Validate bio
if 150 <= len(profile['bio']) <= 250:
    print(f'✓ bio length valid: {len(profile[\"bio\"])} chars')
else:
    print(f'ERROR: bio length invalid: {len(profile[\"bio\"])} (150-250)')

# Validate persona
if 1500 <= len(profile['persona']) <= 2500:
    print(f'✓ persona length valid: {len(profile[\"persona\"])} chars')
else:
    print(f'ERROR: persona length invalid: {len(profile[\"persona\"])} (1500-2500)')

# Check for newlines in persona
if '\n' not in profile['persona'] and '\r' not in profile['persona']:
    print('✓ persona has no newlines')
else:
    print('ERROR: persona contains newlines')

# Validate gender
if profile['gender'] == 'other':
    print('✓ gender is correct: \"other\"')
else:
    print(f'ERROR: gender should be \"other\", got: {profile[\"gender\"]}')

# Validate mbti pattern
mbti_pattern = r'^[EI][SN][TF][JP]$'
if re.match(mbti_pattern, profile['mbti']):
    print(f'✓ mbti pattern valid: {profile[\"mbti\"]}')
else:
    print(f'ERROR: mbti pattern invalid: {profile[\"mbti\"]}')

# Validate age
if profile['age'] == 30:
    print(f'✓ age is correct: {profile[\"age\"]}')
else:
    print(f'ERROR: age should be 30, got: {profile[\"age\"]}')

# Validate country is Chinese
country = profile['country']
if '美' in country or '国' in country:
    print(f'✓ country is Chinese: {country}')
else:
    print(f'ERROR: country should be Chinese: {country}')

# Validate profession is Chinese
profession = profile['profession']
if '人' in profession or '工' in profession:
    print(f'✓ profession is Chinese: {profession}')
else:
    print(f'ERROR: profession should be Chinese: {profession}')

# Validate interested_topics
topics = profile['interested_topics']
if 3 <= len(topics) <= 10:
    print(f'✓ interested_topics count valid: {len(topics)} (3-10)')
else:
    print(f'ERROR: interested_topics count invalid: {len(topics)} (3-10)')

# Check all topics are Chinese
all_chinese = all(any(c in t for c in ['中', '人', '工', '智', '能', '机', '学', 'AI', 'AI']) for t in topics)
if all_chinese:
    print('✓ All interested_topics are in Chinese')
else:
    print('ERROR: Some interested_topics are not in Chinese')

print()
print('=== VALIDATION COMPLETE ===')
"

